if(!exists('collections_backtest',mode='function'))library(creditratingsystem)
actions<-lapply(0:1,function(i)list(action_id=paste0('action',i),account_id=paste0('a',i),treatment_id=paste0('t',i),action_type='CONTACT',stage='ASSIGNED',occurred_at='2024-01-01',known_at='2024-01-01'));states<-lapply(0:1,function(i)list(account_id=paste0('a',i),state_event_id=paste0('s',i),state='DEFAULT',occurred_at='2024-01-01',known_at='2024-01-01'));rule<-list(rule_id='explicit',version='1',problem_states='DEFAULT',clean_states='CLEAN',terminal_states='CLOSED',default_states='DEFAULT',probation_days=10,separation_days=15);coverage<-lapply(0:1,function(i)list(account_id=paste0('a',i),observed_from='2024-01-01',observed_through='2024-02-15',known_at='2024-02-15'));episodes<-build_collections_episodes(states,actions,coverage,rule,evaluation_cutoff='2024-02-15')$value;forecasts<-cash<-capture<-list()
for(i in 0:1){ep<-episodes$episodes[[i+1]];forecasts[[i+1]]<-list(prediction_id=paste0('p',i),entity_id=paste0('a',i),account_id=paste0('a',i),episode_id=ep$episode_id,index_action_id=paste0('action',i),cluster_id=paste0('g',i),segment='collections',as_of='2024-01-01',forecast_known_at='2024-01-01',horizon_end='2024-01-31',model_id='collections',model_version='1',parameter_version='1',predicted_cashflows=list(list(cashflow_id='pred-r',kind='RECOVERY',amount=if(i==0)50 else 40,currency='EUR',occurred_at='2024-01-15'),list(cashflow_id='pred-c',kind='COST',amount=5,currency='EUR',occurred_at='2024-01-10')));cash[[i+1]]<-list(cashflow_id=paste0('cost',i),episode_id=ep$episode_id,kind='COST',amount=5,currency='EUR',occurred_at='2024-01-10',known_at='2024-01-10');capture[[i+1]]<-list(episode_id=ep$episode_id,observed_from='2024-01-01',observed_through='2024-01-31',known_at='2024-02-01')}
cash[[3]]<-list(cashflow_id='recovery',episode_id=episodes$episodes[[1]]$episode_id,kind='RECOVERY',amount=40,currency='EUR',occurred_at='2024-01-20',known_at='2024-01-20');cash[[4]]<-list(cashflow_id='late-recovery',episode_id=episodes$episodes[[2]]$episode_id,kind='RECOVERY',amount=100,currency='EUR',occurred_at='2024-01-25',known_at='2024-03-01');d<-list(model_id='collections',model_version='1',parameter_version='1',data_fingerprint='two-episodes',population_id='collections',split_id='holdout',prediction_origin='HOLDOUT',evaluation_cutoff='2024-02-15',currency='EUR',target=list(event='default',horizon=30,time_unit='days',probability_measure='PHYSICAL',conditioning='default'));discount<-list(method='flat_effective_annual',day_count='ACT_365F',annual_rate=0,currency='EUR',known_at='2023-12-01',reference='fixed-zero-curve')
run<-function(...)collections_backtest(forecasts,episodes,cash,actions,capture,discount_contract=discount,design=d,... )$value
r<-run(uncertainty='none');m<-r$metrics$overall;stopifnot(m$discounted_recovery$bias==25,m$discounted_cost$bias==0,m$discounted_net$bias==25,m$recovery_weighted_days$bias==-5,r$diagnostics$episode_status_counts$OPEN==2,!r$diagnostics$causal_action_effect_identified,!r$diagnostics$open_episodes_treated_as_closed,!'late-recovery'%in%unlist(r$diagnostics$forecast_traces[[2]]$observed_cashflow_ids))
r<-run(uncertainty='cluster_bootstrap',cluster_resamples=list(c('g0','g0'),c('g1','g1')));stopifnot(abs(r$uncertainty$intervals[['discounted_recovery/bias']]$lower-10.75)<1e-12,r$uncertainty$intervals[['recovery_weighted_days/bias']]$reason=='NON_ESTIMABLE_RESAMPLE')
discount$annual_rate<-.1;r<-run(uncertainty='none');expected<-(50*1.1^(-14/365)-40*1.1^(-19/365)+40*1.1^(-14/365))/2;stopifnot(abs(r$metrics$overall$discounted_recovery$bias-expected)<1e-12,inherits(try(run(uncertainty='none',context=list(currency='USD')),silent=TRUE),'try-error'))
capture[[2]]$observed_through<-'2024-01-15';r<-run(uncertainty='none');stopifnot(r$coverage$included_count==1,r$coverage$exclusion_counts$INCOMPLETE_CASHFLOW_CAPTURE==1);actions[[1]]$action_type<-'CHANGED_AFTER_OUTCOME';stopifnot(inherits(try(run(uncertainty='none'),silent=TRUE),'try-error'))
